UPDATE businesses SET description = 'The Office Zone is a flexible workspace provider based in Centurion, offering serviced and private offices, coworking spaces, virtual-office packages and meeting rooms for businesses that don''t want the commitment of a traditional lease. Facilities available to tenants and visitors include fully furnished workspaces, mail handling, office cleaning, printing, telephone-answering services, staffed reception, shared kitchens, administrative support and 24-hour access, giving clients a ready-to-use office environment without managing their own premises. The company serves entrepreneurs, freelancers, remote workers, business travellers, small businesses and larger companies that need short-term or flexible office and meeting space in the Centurion area. Virtual-office clients can use the business address for registration and correspondence purposes while working remotely, while coworking members and private-office tenants get access to the shared amenities and support services on site. The emphasis on flexibility, from hot-desking through to private suites, allows businesses to scale their footprint up or down as needed, making The Office Zone a practical option for companies in transition, start-ups testing a Centurion base, or firms requiring a professional meeting venue without a permanent office.', description_enriched_at = datetime('now') WHERE slug = 'the-office-zone-monavoni' AND description = 'The Office Zone is a serviced-office and coworking provider offering virtual offices, private offices, hot desks, boardrooms and call-answering with reception support, based in Monavoni, Centurion.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
